    def obtener_ventas(self, page=0, size=50):
        headers = {
            "Accept": "application/json",
            "Cookie": self.cookie, # <--- Enviamos la sesión activa
            "x-vendor-id": self.vendor_id,
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36"
        }
        params = {"page": page, "size": size}
        
        try:
            response = requests.get(self.url, headers=headers, params=params)
            # Si responde HTML de nuevo, es que el cookie expiró o es incorrecto
            if response.text.startswith("<!DOCTYPE"):
                print("ALERTA: Paris devolvió HTML (Sesión expirada)")
                return []
            
            return response.json() if response.status_code == 200 else []
        except Exception as e:
            print(f"Error: {str(e)}")
            return []

